"""Human-readable .26 change inventory from the applied plan and validator."""
from pathlib import Path
import json,subprocess
R=Path(__file__).resolve().parents[1]
def read(n):return json.loads((R/n).read_text())
def main():
 w=read('data/world.json');r=read('data/geography_0226_report.json');plan=read('data/state_plan_0226.json');old=json.loads(subprocess.check_output(['git','show','aeacb59:data/world.json'],cwd=R));md=read('data/md_geography_reference.json')
 lines=['# Bunny World 0.2.0.26 — State detail','', 'Apply to the confirmed 0.2.0.25 project (GitHub main at aeacb59). This is a changed-files patch. Close Godot, extract into the project root, replace files, run Prepare_BunnyWorld.bat, then start a fresh campaign in Godot 4.5.1 Standard or export a new release EXE. Old campaign saves belong to the previous scenario.','', '29 new states; 224 countries, 1,264 states, 13,308 land provinces. All four canonical province tiles are byte-identical to .25, including Antarctica. No province was cut, added or deleted. Every country retains exactly its population, building inventory, building-slot total and province ownership. Shared borders and map resources are rebuilt from the same province membership source.','', '| Country | Before | After | MD guide |','|---|---:|---:|---:|']
 for c in r['counts']:lines.append(f"| {c['country']} | {c['before']} | {c['after']} | {c['md']} |")
 lines+=['', 'Taiwan and Afghanistan are unchanged. The Philippines and all other explicit exclusions are unchanged. Previously approved mergers remain, including one Micronesia state, four Papua New Guinea states, the Mindanao union, Mariana Islands and the Hawaii island exceptions. No removed island, reef, military-base or tiny-territory state is recreated.','', '## New states and whole-province membership','', '| ID | Country | New state | Member province IDs |','|---:|---|---|---|']
 for s in r['new_states']:lines.append(f"| {s['id']} | {w['countries'][s['country']]['name']} | {s['name']} | {', '.join(map(str,s['provinces']))} |")
 lines+=['', '## Every reviewed regional grouping','', 'These are whole-province approximations of real regional units, not exact administrative polygons. Maximum native land-pixel overlap determines a boundary province; no rectangular cuts or new fragments. Modern administrative references guide placement and names, without asserting that every division had the same legal boundary in 2000. MD supplies counts/naming context only; no MD geometry is used.','', 'Songjiang is a gameplay grouping of the listed southern/eastern Heilongjiang prefectures, rather than a claim to reproduce the historic province. Northern Hebei includes Tangshan and Qinhuangdao to retain a connected mainland grouping around Beijing/Tianjin. Western Sichuan includes Panzhihua with Liangshan. Western Guangdong keeps Yunfu with the western coastal region so that neither mainland remainder is disconnected.','', 'Morocco uses real pre-2015 member regions: composite names explicitly identify the regions grouped together. The incorrectly placed Casablanca-Settat label is replaced. Colombia uses department groups, transferring Meta to Orinoquía, Boyacá to Cundinamarca–Boyacá and Córdoba to Caribe. Retained Caribbean islands/banks remain merged into Caribe.','']
 for p in plan['plans']:
  lines+=['### '+p['key'],'']
  for g in p['groups']:
   if not g['provinces']:continue
   s=w['regions'][str(g['id'])];lines += [f"- **{s['name']} ({s['id']})** — population {s['population']:,}; capital {s['state_capital']}. Reference members: {', '.join(g['reference_members'])}. Provinces: {', '.join(map(str,g['provinces']))}."]
  low=[a for a in p['assignments']if a['fit']<.6]
  if low:lines+=['', 'Boundary/source-fit review: '+ '; '.join(f"province {a['province']}: {a['fit']:.1%} winning share, {a['source_coverage']:.1%} source coverage"for a in low)+'. Full per-province vote counts are in data/state_plan_0226.json. Zero coverage occurs at source shoreline/remote-island mismatches, assigned to the nearest existing regional group, never a new island state.']
  lines+=['']
 lines+=['## Renamed retained states','', '| State ID | Previous name | New name |','|---:|---|---|']
 for n in r['renames']:lines.append(f"| {n['id']} | {n['before']} | {n['after']} |")
 lines+=['', '## Skipped and unresolved choices','']
 for s in r['skipped']:lines+=['- **'+s['name']+'** — '+s['reason']]
 lines+=['', 'Optional-country states were not audited to the same regional depth as the six core countries in this patch. This report does not claim that none could benefit from a future split.','', '## Population, buildings and references','',r['population_method'],'', 'These population shares are explicit coarse estimates, not researched regional census counts. This patch does not implement the separate state-specific religion/education/age overhaul; new states inherit the existing complete national demographic profile. The next demographic pass should refine these shares. World population remains 6,144,737,528.','', 'Each old state total is apportioned independently with largest-remainder rounding; regrouped states sum their contributions. Buildings and slots use the same retained-total allocation, with no cap that deletes inventory and no copying that duplicates it. Source-state IDs/cores/claims remain inherited metadata; regroupings union parent metadata, so those legacy claims remain coarse state-level annotations. No starting province owner changes.','', 'Country capitals follow their existing capital province. Existing state capitals remain where possible; new states use an already mapped settlement, otherwise an explicitly marked province administrative anchor. City references, scenery state references/weights, urban accounting, protected-territory references, country lists and adjacency are refreshed.','', '## Sources and reproducibility','', '- Natural Earth ADM1: tools/cartography/geographic_subdivisions.geojson (public domain, already in the project).', '- GADM 4.1 ADM2 local references for China, India, Pakistan and Syria: https://gadm.org/data.html . Download URLs/checksums in data/state_plan_0226.json. Source archives and polygon geometry are not included; https://gadm.org/license.html .', '- Existing mapped settlement population ranks in data/cities.json and current province areas supply the disclosed allocation proxy.', '- MD reference: data/md_geography_reference.json, previously verified against the supplied MD state-history archive in the .25 audit.', '- Review: python tools/review_states_0226.py --references /path/to/local/gadm/archives (run against .25, archives named CHN_2.zip, IND_2.zip, PAK_2.zip and SYR_2.zip).', '- Apply once to .25: python tools/apply_states_0226.py .', '- Build: python tools/build_map.py --godot /path/to/Godot_4.5.1 . A fresh checkout needs the normal Godot editor/import step first so global script classes are registered.', '- Validate: python tests/geography_0226_tests.py ; python tools/build_map.py --check ; python tools/restore_repository_assets.py --verify-only .','', '## Validation and your short test','']
 v=R/'validation_0226/geography_results.json'
 if v.exists():lines+=['Data validator: '+str(read('validation_0226/geography_results.json')['checks'])+' checks passed, including exact country totals, exclusions, identical province tiles, references and mainland connectivity.']
 runtime=R/'validation_0226/runtime_results.json'
 if runtime.exists():lines+=['','Godot runtime: '+str(read('validation_0226/runtime_results.json')['checks'])+' checks passed, including new-state selection/highlight and live ownership lookup.']
 lines+=['', 'Native Windows graphics have not been tested here. In your fresh campaign, inspect one new state in each target country; hover it in the country state browser; check a new state capital and inline demographics; transfer a new state with the existing owner command; confirm its provinces and color update. Briefly check Taiwan/Afghanistan, Micronesia, Papua New Guinea and Antarctica. Map performance changes are outside this patch.','']
 text='\n'.join(lines);(R/'documentation/state_audit_0226/STATE_CHANGES.md').write_text(text)
 (R.parent/'BunnyWorld_0_2_0_26_State_Changes.md').write_text(text)
 counts=['# All-country counts after 0.2.0.26','','MD is a guide, not a mandatory quota. Explicit exclusions and approved island mergers take precedence. Historical .25 audit files remain a record of .25.','','| Country | Tag | .25 | .26 | MD |','|---|---|---:|---:|---:|']
 for t,c in sorted(w['countries'].items(),key=lambda x:x[1]['name']):counts.append(f"| {c['name']} | {t} | {len(old['countries'][t]['regions'])} | {len(c['regions'])} | {md['countries'].get(t,{}).get('states','—')} |")
 (R/'documentation/state_audit_0226/COUNTRY_COUNTS.md').write_text('\n'.join(counts)+'\n')
 print('STATE_REPORT_READY')
if __name__=='__main__':main()
